// Block-based scripting (events + actions) for Asternal Engine
import type { Entity, EntityKind, RuntimeInput, RuntimeState, Scene } from "./core";
import { intersects, KIND_PRESETS, uid as makeId } from "./core";
import { playSound, vibrate, type SoundName, SOUND_NAMES } from "./sfx";

export type EventType =
  | "onStart"
  | "onCreate"
  | "onUpdate"
  | "onCollide"
  | "onKeyDown"
  | "onScoreReach"
  | "onDestroyed"
  | "onDestroy"
  | "onTimer"
  | "onLeaveScreen"
  | "onLand"
  | "onWin"
  | "onLose";

export type BlockKind =
  // existing
  | "jump"
  | "setVx"
  | "setVy"
  | "addScore"
  | "destroySelf"
  | "destroyOther"
  | "win"
  | "lose"
  | "teleport"
  | "log"
  | "playSound"
  | "vibrate"
  | "shake"
  | "setColor"
  | "setSize"
  | "setGravity"
  | "setControllable"
  | "impulse"
  | "setVisible"
  | "restartScene"
  | "setBg"
  | "if"
  // 30 new
  | "setX"
  | "setY"
  | "moveX"
  | "moveY"
  | "flipVx"
  | "flipVy"
  | "bounceY"
  | "stop"
  | "setSpeed"
  | "setOpacity"
  | "setHazard"
  | "setSolid"
  | "setCollectible"
  | "setGoalFlag"
  | "addLives"
  | "setLives"
  | "setScore"
  | "resetScore"
  | "spawnEntity"
  | "cloneSelf"
  | "setSceneGravity"
  | "playRandomSound"
  | "wrapScreen"
  | "faceTarget"
  | "chase"
  | "setHitbox"
  | "clearHitbox"
  | "removeAllOf"
  | "comment"
  | "hurtPlayer"
  | "wait"
  | "setFacing"
  | "knockback"
  | "pushAway";

export interface Block {
  id: string;
  kind: BlockKind;
  value?: number;
  x?: number;
  y?: number;
  w?: number;
  h?: number;
  text?: string;
  sound?: SoundName;
  color?: string;
  bool?: boolean;
  cond?: "scoreGte" | "scoreLte";
  thenBlocks?: Block[];
}

export interface Script {
  id: string;
  event: EventType;
  withKind?: EntityKind | "any";          // onCollide
  key?: "left" | "right" | "jump";        // onKeyDown
  threshold?: number;                     // onScoreReach
  interval?: number;                      // onTimer (ms)
  blocks: Block[];
}

